namespace workbench {
    export namespace configuration {
        declare var CodeMirror: any;
        let activeEditor: any = null;

        /** Keep the textarea submitted by both the native form and the in-page router current. */
        export function save(): void {
            if (activeEditor) {
                activeEditor.save();
            }
        }

        /** Configuration text belongs to this mount only; it is never persisted in browser storage. */
        export function mount(outlet: HTMLElement): () => void {
            const textarea = outlet.querySelector<HTMLTextAreaElement>('#configuration');
            if (!textarea) {
                return () => {};
            }
            // Lit can reuse a textarea whose native value was dirtied by the previous editor. A new route mount
            // starts from its freshly rendered text; Back/Forward restores that history entry's draft after mount.
            textarea.value = textarea.defaultValue;
            if (typeof CodeMirror === 'undefined') {
                return () => {};
            }
            const editor = CodeMirror.fromTextArea(textarea, {
                lineNumbers: true,
                screenReaderLabel: 'Repository configuration (Turtle)',
                lineWrapping: false,
                indentUnit: 2,
                tabSize: 2,
                mode: null
            });
            activeEditor = editor;
            const changed = () => {
                editor.save();
                const view = textarea.ownerDocument.defaultView;
                if (view && typeof view.Event === 'function') {
                    textarea.dispatchEvent(new view.Event('input', { bubbles: true }));
                }
            };
            editor.on('change', changed);
            const sizing = (workbench as any).editorSizing;
            const handle = outlet.querySelector('#configuration-editor-resize');
            const releaseSizing = sizing && handle
                ? sizing.install(editor, handle, 'rdf4j.workbench.configuration-editor-height.v1') : () => {};
            editor.refresh();
            let disposed = false;
            return () => {
                if (disposed) { return; }
                disposed = true;
                releaseSizing();
                editor.off('change', changed);
                editor.toTextArea();
                if (activeEditor === editor) {
                    activeEditor = null;
                }
            };
        }
    }
}
